using System;namespace Recovered.Gameplay {public static class PtlMaterialDeclarations {public static void Refresh(SoundSetupImage m,uint material,Func<SoundSetupImage,uint,uint[],uint> external,PtlVertexDeclarations.DeviceCall device){Observe(m,material,external,device,null);}public static void Observe(SoundSetupImage m,uint material,Func<SoundSetupImage,uint,uint[],uint> external,PtlVertexDeclarations.DeviceCall device,Action<uint> tokenObserver){PtlMaterialTokens.Observe(m,material,delegate(SoundSetupImage image,uint address,uint[] values){if(address==0x7418c0)return PtlVertexDeclarations.Resolve(image,values[0],device);return external(image,address,values);},tokenObserver);}}}
